package org.elasticsearch.plugin.analysis.vi;

import org.elasticsearch.plugin.Extensible;
import org.elasticsearch.plugin.analysis.TokenizerFactory;
import org.elasticsearch.plugin.scanner.ClassReaders;
import org.elasticsearch.plugin.scanner.NamedComponentScanner;
import org.elasticsearch.test.ESTestCase;

import java.net.URL;
import java.util.Map;
import java.util.Set;

/**
 * {@code named_components.json} is checked in rather than generated by the build, so make sure it matches what the
 * official scanner (used by Elasticsearch's Gradle plugin) finds in the {@code @NamedComponent} annotations.
 */
public class NamedComponentsTests extends ESTestCase {

    public void testNamedComponentsFileMatchesAnnotations() throws Exception {
        Set<URL> classPath = Set.of(
            location(VietnameseTokenizerFactory.class),
            location(Extensible.class),
            location(TokenizerFactory.class)
        );
        Map<String, Map<String, String>> scanned = NamedComponentScanner.scanForNamedClasses(ClassReaders.ofPaths(classPath));
        assertEquals(scanned, StablePluginTestHelper.namedComponents());
    }

    private static URL location(Class<?> clazz) {
        return clazz.getProtectionDomain().getCodeSource().getLocation();
    }
}
